import {cloud} from './supabase.js';

const panelId='cloud-sync-panel';
const openDb=()=>new Promise((resolve,reject)=>{let request=indexedDB.open('paper-english',1);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});
const readData=async()=>{let db=await openDb();return new Promise((resolve,reject)=>{let request=db.transaction('data').objectStore('data').get('app');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})};
const writeData=async data=>{let db=await openDb();return new Promise((resolve,reject)=>{let tx=db.transaction('data','readwrite');tx.objectStore('data').put(data,'app');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})};
const message=text=>{let node=document.createElement('div');node.className='toast';node.textContent=text;document.body.append(node);setTimeout(()=>node.remove(),3500)};
const session=()=>cloud.session();
const activeSession=async()=>{let active=session();if(active?.expires_at&&active.expires_at<Date.now()/1000+60){active=await cloud.refresh(active.refresh_token);cloud.storeSession(active)}return active};
const sync=async(show=false)=>{let active=await activeSession();if(!active||!cloud.configured())return;try{await cloud.save(active.user.id,await readData(),active.access_token);if(show)message('Đã đồng bộ dữ liệu.')}catch(error){if(show)message(error.message)}};

function panel(){
  if(!cloud.configured())return `<section id="${panelId}" class="paper setting-panel backup-panel"><div class="panel-heading"><span class="panel-icon lavender-icon">☁</span><div><span class="eyebrow">ĐỒNG BỘ SUPABASE</span><h2>Kết nối Supabase</h2></div></div><p>Dán Project URL và Publishable/anon key từ Supabase Dashboard → Project Settings → API. Đây là khóa công khai, không phải mật khẩu database.</p><div class="form-grid"><label>Project URL<input id="cloud-url" type="url" placeholder="https://xxxxx.supabase.co"></label><label>Publishable / anon key<input id="cloud-key" type="text" autocomplete="off" placeholder="sb_publishable_... hoặc eyJ..."></label></div><div class="backup-actions"><button class="button dark" data-cloud="configure">Kết nối Supabase</button></div></section>`;
  let active=session();
  if(active)return `<section id="${panelId}" class="paper setting-panel backup-panel"><div class="panel-heading"><span class="panel-icon lavender-icon">☁</span><div><span class="eyebrow">ĐỒNG BỘ SUPABASE</span><h2>Đã đăng nhập</h2></div></div><p>${active.user.email}. Thư viện và tiến độ sẽ được đồng bộ giữa các thiết bị dùng tài khoản này.</p><div class="backup-actions"><button class="button dark" data-cloud="sync">↻ &nbsp; Đồng bộ ngay</button><button class="button" data-cloud="signout">Đăng xuất</button></div><span class="storage-caption">◈ &nbsp; Chỉ tài khoản của bạn có thể đọc dữ liệu</span></section>`;
  return `<section id="${panelId}" class="paper setting-panel backup-panel"><div class="panel-heading"><span class="panel-icon lavender-icon">☁</span><div><span class="eyebrow">ĐỒNG BỘ SUPABASE</span><h2>Đồng bộ thiết bị</h2></div></div><p>Đăng nhập cùng một email trên laptop và iPad để dùng chung thư viện và tiến độ.</p><div class="form-grid"><label>Email<input id="cloud-email" type="email" autocomplete="email" placeholder="ban@example.com"></label><label>Mật khẩu<input id="cloud-password" type="password" autocomplete="current-password" minlength="6" placeholder="Ít nhất 6 ký tự"></label></div><div class="backup-actions"><button class="button dark" data-cloud="signin">Đăng nhập</button><button class="button" data-cloud="signup">Tạo tài khoản</button></div></section>`;
}

function installPanel(){let column=document.querySelector('.settings-layout .settings-column');if(!column||document.querySelector(`#${panelId}`))return;column.insertAdjacentHTML('afterbegin',panel())}
new MutationObserver(installPanel).observe(document.querySelector('#app'),{childList:true,subtree:true});installPanel();
document.addEventListener('click',()=>setTimeout(installPanel));
setInterval(installPanel,500);

document.addEventListener('click',async event=>{let button=event.target.closest('[data-cloud]');if(!button)return;let action=button.dataset.cloud;if(action==='configure'){try{cloud.configure(document.querySelector('#cloud-url')?.value||'',document.querySelector('#cloud-key')?.value||'');location.reload()}catch(error){message(error.message)}return}if(action==='sync'){await sync(true);return}if(action==='signout'){await cloud.signOut(session()?.access_token);message('Đã đăng xuất. Dữ liệu cục bộ vẫn còn trên thiết bị này.');location.reload();return}let email=document.querySelector('#cloud-email')?.value.trim(),password=document.querySelector('#cloud-password')?.value;if(!email||!password)return message('Hãy nhập email và mật khẩu.');if(password.length<6)return message('Mật khẩu cần ít nhất 6 ký tự.');try{let result=action==='signup'?await cloud.signUp(email,password):await cloud.signIn(email,password);if(!result.session)return message('Hãy mở email để xác nhận tài khoản, rồi đăng nhập.');cloud.storeSession(result.session);let remote=await cloud.load(result.user.id,result.session.access_token);if(remote){await writeData(remote);message('Đã tải dữ liệu từ Supabase.')}else{await sync();message('Đã tạo vùng dữ liệu đồng bộ.')}location.reload()}catch(error){message(error.message)}});

// Keep the remote copy fresh while this static app writes to IndexedDB locally.
setInterval(()=>sync(false),5000);
